window.KhaemenesScience9CumulativeQuestionBank=[{"id":"u10-q-q01","domain":"Systems","prompt":"A reservoir is:","options":["A stored quantity of matter or energy","A transfer rate only","Always a lake","A feedback"],"answer":0,"explanation":"Reservoir means stored amount within a defined system.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz","type":"model"},{"id":"u10-q-q02","domain":"Feedback","prompt":"A negative feedback:","options":["Amplifies an initial change","Opposes part of an initial change","Eliminates all change","Is always harmful"],"answer":1,"explanation":"Negative feedback dampens or opposes change.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz","type":"model"},{"id":"u10-q-q03","domain":"Interior","prompt":"S waves support a liquid outer core because they:","options":["Measure age directly","Travel fastest in liquids","Do not propagate through liquids","Only occur at the surface"],"answer":2,"explanation":"S waves require shear rigidity.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz","type":"concept"},{"id":"u10-q-q04","domain":"Plate boundary","prompt":"Transform boundaries mainly involve:","options":["Crust creation only","Subduction only","No earthquakes","Lateral plate motion"],"answer":3,"explanation":"Transform plates slide past each other.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz","type":"model"},{"id":"u10-q-q05","domain":"Rock cycle","prompt":"Which pathway is possible?","options":["Sedimentary rock melting and later crystallizing as igneous rock","Only one fixed sequence","Igneous rock never weathering","Metamorphic rock forming only at the surface"],"answer":0,"explanation":"The rock cycle has many pathways.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz","type":"model"},{"id":"u10-q-q06","domain":"Weathering","prompt":"Weathering differs from erosion because weathering:","options":["Requires rivers","Breaks material down in place","Always transports sediment","Occurs only chemically"],"answer":1,"explanation":"Weathering is breakdown in place.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz","type":"concept"},{"id":"u10-q-q07","domain":"Water budget","prompt":"P=90, ET=35, runoff=40 mm. Δstorage is:","options":["165 mm","5 mm","15 mm","55 mm"],"answer":2,"explanation":"90−35−40=15 mm.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz","type":"concept"},{"id":"u10-q-q08","domain":"Groundwater","prompt":"Groundwater is stored mainly in:","options":["A single global underground river","Clouds","The inner core","Pores and fractures"],"answer":3,"explanation":"It occupies connected pore spaces and fractures.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz","type":"concept"},{"id":"u10-q-q09","domain":"Carbon","prompt":"Which transfers carbon from atmosphere to biosphere?","options":["Photosynthesis","Respiration","Combustion","Volcanism"],"answer":0,"explanation":"Photosynthesis fixes atmospheric CO₂.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz","type":"concept"},{"id":"u10-q-q10","domain":"Nitrogen","prompt":"Denitrification commonly returns nitrogen to:","options":["Sunlight","The atmosphere as N₂","Only rocks","The inner core"],"answer":1,"explanation":"Denitrification converts reactive nitrogen toward gaseous forms.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz","type":"concept"},{"id":"u10-q-q11","domain":"Phosphorus","prompt":"A major source of phosphate to ecosystems is:","options":["Solar radiation","Earth’s outer core","Rock weathering","Atmospheric N₂ fixation"],"answer":2,"explanation":"Weathering releases phosphate minerals.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz","type":"model"},{"id":"u10-q-q12","domain":"Residence time","prompt":"Reservoir 500, outflow 25/year gives:","options":["25 years","12,500 years","5 years","20 years"],"answer":3,"explanation":"500/25=20 years.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz","type":"concept"},{"id":"u10-q-q13","domain":"Climate","prompt":"Earth’s long-term energy balance compares:","options":["Incoming, reflected, absorbed, and outgoing energy","Only rainfall","Only wind","Only plate speed"],"answer":0,"explanation":"Climate energy accounting tracks radiative flows.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz","type":"concept"},{"id":"u10-q-q14","domain":"Albedo","prompt":"Higher albedo means:","options":["Higher density","A larger reflected fraction","More absorption in every case","No reflection"],"answer":1,"explanation":"Albedo is the reflected fraction.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz","type":"quantitative"},{"id":"u10-q-q15","domain":"Greenhouse gas","prompt":"Which is a greenhouse gas?","options":["Argon only","Helium only","Carbon dioxide","Nitrogen only"],"answer":2,"explanation":"CO₂ absorbs and emits infrared radiation.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz","type":"model"},{"id":"u10-q-q16","domain":"Climate evidence","prompt":"Which record directly measures atmospheric composition?","options":["A plate-boundary map","A mineral hardness test","A river cross-section","Instrumental gas concentration data"],"answer":3,"explanation":"Atmospheric monitoring measures gas concentrations.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz","type":"evidence"},{"id":"u10-q-q17","domain":"Human modification","prompt":"Fertilizer can alter:","options":["Nitrogen and phosphorus fluxes","Plate velocity only","Earth’s core state","Solar output"],"answer":0,"explanation":"Fertilizer changes reactive nutrient transfers.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz","type":"concept"},{"id":"u10-q-q18","domain":"Hazards","prompt":"Hazard maps are best used to:","options":["Replace emergency plans","Support risk planning, not exact event timing","Predict the exact next earthquake","Prove no risk elsewhere"],"answer":1,"explanation":"They inform probabilities and exposure.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz","type":"concept"},{"id":"u10-q-q19","domain":"Justice","prompt":"Environmental risk is unequal because:","options":["Data are never useful","Hazards affect only cities","Exposure, vulnerability, resources, and decision power differ","Physical laws change by neighborhood"],"answer":2,"explanation":"Social and infrastructural conditions shape risk.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz","type":"evidence"},{"id":"u10-q-q20","domain":"Safety","prompt":"Which is prohibited?","options":["Using supplied watershed data","Observing rocks from a public trail","Analyzing a map","Entering floodwater to collect a sample"],"answer":3,"explanation":"Floodwater is hazardous and unpredictable.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz","type":"concept"},{"id":"u10-a-a01","domain":"System boundary","prompt":"Why define a system boundary?","options":["To identify included reservoirs, transfers, inputs, and outputs","To prove the system is isolated","To remove uncertainty","To make every model exact"],"answer":0,"explanation":"Boundaries determine what is counted and what crosses the system.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"model"},{"id":"u10-a-a02","domain":"Flux units","prompt":"Which unit is appropriate for a flux?","options":["degrees","kg/year","kg only","metres only"],"answer":1,"explanation":"A flux is amount per time.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"quantitative"},{"id":"u10-a-a03","domain":"Density","prompt":"A 240 g rock occupies 80 cm³. Density is:","options":["19,200 g/cm³","0.33 g/cm³","3.0 g/cm³","160 g/cm³"],"answer":2,"explanation":"240/80=3.0 g/cm³.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"quantitative"},{"id":"u10-a-a04","domain":"Seismic lag","prompt":"P arrives at 12 s and S at 21 s. S–P lag is:","options":["12 s","21 s","33 s","9 s"],"answer":3,"explanation":"21−12=9 s.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"quantitative"},{"id":"u10-a-a05","domain":"Epicenter","prompt":"One station’s S–P lag gives:","options":["A distance estimate only","Exact latitude and longitude","Earthquake magnitude only","Fault depth exactly"],"answer":0,"explanation":"Direction requires more stations or information.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u10-a-a06","domain":"Convection","prompt":"Convection is driven by:","options":["Magnetic poles alone","Density differences and gravity with energy transfer","Only sound waves","No material motion"],"answer":1,"explanation":"Buoyancy and gravity drive convective movement.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u10-a-a07","domain":"Divergent boundary","prompt":"A continental rift is associated with:","options":["Collision only","No tectonics","Divergence","Transform motion"],"answer":2,"explanation":"Rifts form where continental lithosphere extends.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u10-a-a08","domain":"Subduction","prompt":"Oceanic lithosphere commonly subducts because it is:","options":["Always younger than continental crust","Liquid","Made only of granite","Relatively dense"],"answer":3,"explanation":"Cooling oceanic lithosphere can become dense enough to sink.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u10-a-a09","domain":"Weathering","prompt":"Oxidation of iron-bearing minerals is:","options":["Chemical weathering","Physical erosion","Deposition","Melting"],"answer":0,"explanation":"Oxidation changes mineral chemistry.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u10-a-a10","domain":"Deposition","prompt":"Deposition occurs when:","options":["Gravity disappears","Transport capacity decreases","Weathering stops globally","Water becomes pure"],"answer":1,"explanation":"Sediment settles when transport can no longer carry it.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u10-a-a11","domain":"Water budget","prompt":"P=120, ET=55, runoff=45 mm. Storage change is:","options":["220 mm","10 mm","20 mm","65 mm"],"answer":2,"explanation":"120−55−45=20 mm.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u10-a-a12","domain":"Infiltration","prompt":"Which generally promotes infiltration?","options":["Continuous pavement","Compacted surface only","A sealed roof","Permeable soil and vegetation"],"answer":3,"explanation":"Permeability and roots favor entry of water.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u10-a-a13","domain":"Aquifer","prompt":"An aquifer is:","options":["A material body that stores and transmits useful groundwater","Any underground cavity","The water table itself","A surface watershed"],"answer":0,"explanation":"Aquifers transmit and store groundwater.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u10-a-a14","domain":"Carbon balance","prompt":"Inputs 90, outputs 75 units/year produce:","options":["165 units/year","+15 units/year","−15 units/year","0"],"answer":1,"explanation":"Net change is +15.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u10-a-a15","domain":"Carbon pathway","prompt":"Which is a slow carbon pathway?","options":["Photosynthesis","Daily air–sea exchange","Carbonate sediment burial","Respiration"],"answer":2,"explanation":"Geological burial is slow relative to biological exchange.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u10-a-a16","domain":"Nitrogen fixation","prompt":"Which can fix nitrogen?","options":["All animals directly","Sunlight alone","Phosphate rock only","Certain microbes"],"answer":3,"explanation":"Some microbes convert N₂ into reactive nitrogen.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u10-a-a17","domain":"Nitrification","prompt":"Nitrification converts reduced nitrogen toward:","options":["Nitrite and nitrate","Atmospheric carbon dioxide","Phosphate rock","Metallic iron"],"answer":0,"explanation":"Nitrifying microbes oxidize ammonium.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u10-a-a18","domain":"Phosphorus","prompt":"Why can phosphorus limitation occur?","options":["It is destroyed during uptake","Phosphate availability can be low and has no large atmospheric reservoir","Phosphorus is not biological","All rocks dissolve instantly"],"answer":1,"explanation":"Its supply is constrained by geological and biological processes.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u10-a-a19","domain":"Eutrophication","prompt":"A likely sequence is:","options":["Plate motion → nitrate loss only","Evaporation → radioactive decay","Nutrient input → high production → decomposition → oxygen decline","Oxygen rise → no organisms → more nutrients"],"answer":2,"explanation":"This is the classic eutrophication pathway.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u10-a-a20","domain":"Residence time","prompt":"A 3000-unit reservoir with 100-unit/year outflow has:","options":["100 years","300,000 years","3 years","30 years"],"answer":3,"explanation":"3000/100=30 years.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u10-a-a21","domain":"Albedo","prompt":"Incoming 340 W/m², albedo 0.25. Absorbed is:","options":["255 W/m²","340 W/m²","425 W/m²","85 W/m²"],"answer":0,"explanation":"340×0.75=255 W/m².","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"quantitative"},{"id":"u10-a-a22","domain":"Energy imbalance","prompt":"Absorbed 241, outgoing 239 W/m² means:","options":["0","+2 W/m²","+480 W/m²","−2 W/m²"],"answer":1,"explanation":"241−239=+2 W/m².","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u10-a-a23","domain":"Weather","prompt":"Which is weather?","options":["Long-term monsoon statistics","Thirty-year frost frequency","A tornado warning today","A 50-year temperature trend"],"answer":2,"explanation":"Weather is short-term atmospheric condition.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u10-a-a24","domain":"Climate forcing","prompt":"Increasing greenhouse-gas concentration is a:","options":["Plate boundary","Mineral property","Watershed outlet","Radiative forcing"],"answer":3,"explanation":"It alters Earth’s radiative energy balance.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"model"},{"id":"u10-a-a25","domain":"Positive feedback","prompt":"Which is positive?","options":["Warming melts ice, lowering albedo and increasing absorption","Warming increases radiation to space","A thermostat turns cooling on","Weathering consumes some CO₂"],"answer":0,"explanation":"The ice–albedo loop amplifies the initial warming.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"model"},{"id":"u10-a-a26","domain":"Uncertainty","prompt":"Uncertainty means:","options":["Models are useless","A quantified or described limit, not total ignorance","All conclusions are equally likely","No evidence exists"],"answer":1,"explanation":"Uncertainty defines confidence and limitations.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"evidence"},{"id":"u10-a-a27","domain":"Mitigation","prompt":"Which is mitigation?","options":["Expanding evacuation routes","Installing cooling centers","Reducing greenhouse-gas emissions","Raising homes above flood level"],"answer":2,"explanation":"Mitigation reduces the cause or forcing.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u10-a-a28","domain":"Adaptation","prompt":"Which is adaptation?","options":["Reducing fossil-fuel combustion","Capturing methane at a landfill","Improving energy efficiency","Restoring wetlands to reduce coastal flood impacts"],"answer":3,"explanation":"Wetland restoration can reduce vulnerability to flooding.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u10-a-a29","domain":"Risk","prompt":"Risk depends on:","options":["Hazard, exposure, and vulnerability","Hazard alone","Population alone","Weather alone"],"answer":0,"explanation":"Risk emerges from the interaction of these factors.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"evidence"},{"id":"u10-a-a30","domain":"Safety","prompt":"Which field action is inappropriate?","options":["Recording rainfall with a stable gauge","Entering an unstable sinkhole edge","Using public map data","Photographing a stream from a safe bridge"],"answer":1,"explanation":"Sinkholes can collapse and should not be approached.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment","type":"concept"},{"id":"u11-q-q01","domain":"Sky motion","prompt":"Day and night result from:","options":["Earth’s rotation","Earth’s orbit only","The Moon’s phases","The Sun orbiting Earth daily"],"answer":0,"explanation":"Earth rotates approximately once per day.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz","type":"concept"},{"id":"u11-q-q02","domain":"Lunar phases","prompt":"Ordinary lunar phases are caused by:","options":["Earth’s shadow covering the Moon","Changing viewing geometry of the Moon’s sunlit half","Cloud cover","The Moon producing different amounts of light"],"answer":1,"explanation":"The visible fraction changes with geometry.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz","type":"concept"},{"id":"u11-q-q03","domain":"Scale","prompt":"Which unit is most useful for nearby stellar distances?","options":["Pascal","Kilogram","Light-year","Ampere"],"answer":2,"explanation":"Light-years measure large distances.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz","type":"concept"},{"id":"u11-q-q04","domain":"Light-time","prompt":"If light travel time is 500 s and c=3.0×10⁸ m/s, distance is:","options":["6.0×10⁵ m","1.67×10⁻⁶ m","1.5×10⁶ m","1.5×10¹¹ m"],"answer":3,"explanation":"d=ct=3.0×10⁸×500=1.5×10¹¹ m.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz","type":"quantitative"},{"id":"u11-q-q05","domain":"Orbit","prompt":"Gravity in an orbit primarily changes:","options":["Velocity direction and sometimes magnitude","Mass into charge","Time into distance","The object’s chemical identity"],"answer":0,"explanation":"Gravity accelerates the orbiting object.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz","type":"model"},{"id":"u11-q-q06","domain":"Formation","prompt":"Planetary systems form from:","options":["Black holes exclusively","Rotating disks of gas and dust around young stars","Only shattered planets","Empty space without matter"],"answer":1,"explanation":"Protoplanetary disks provide material for accretion.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz","type":"model"},{"id":"u11-q-q07","domain":"Sun","prompt":"The photosphere is:","options":["A planet","The solar-system boundary","The Sun’s visible surface layer","The fusion core"],"answer":2,"explanation":"Most visible sunlight emerges from the photosphere.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz","type":"concept"},{"id":"u11-q-q08","domain":"Space weather","prompt":"Auroras are linked to:","options":["Lunar eclipses","Ocean tides only","Asteroid mining","Charged particles interacting with Earth’s magnetic environment and atmosphere"],"answer":3,"explanation":"Energetic particles excite atmospheric gases.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz","type":"concept"},{"id":"u11-q-q09","domain":"Spectrum","prompt":"A blueshift means observed wavelength is:","options":["Shorter than rest wavelength","Always exactly zero","Unrelated to motion","Longer than rest wavelength"],"answer":0,"explanation":"Approaching line-of-sight motion can shorten wavelength.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz","type":"concept"},{"id":"u11-q-q10","domain":"Telescopes","prompt":"Radio telescopes detect:","options":["Gravity directly","Radio-frequency electromagnetic waves","Sound traveling through space","Only visible light"],"answer":1,"explanation":"Radio is part of the electromagnetic spectrum.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz","type":"concept"},{"id":"u11-q-q11","domain":"Stars","prompt":"Main-sequence stability reflects balance between:","options":["Planetary tides only","Darkness and brightness","Inward gravity and outward pressure effects","Electric charge and magnet color"],"answer":2,"explanation":"Stars maintain dynamic hydrostatic balance.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz","type":"concept"},{"id":"u11-q-q12","domain":"Stellar evolution","prompt":"A lower-mass star is expected eventually to form:","options":["A supermassive black hole directly","A planet without mass loss","An asteroid belt only","A white dwarf after a red-giant and planetary-nebula stage"],"answer":3,"explanation":"Lower-mass stars end as white dwarfs.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz","type":"model"},{"id":"u11-q-q13","domain":"Transit","prompt":"Transit depth mainly constrains:","options":["Planet-to-star area ratio","Galaxy age","Moon phase","Hubble constant"],"answer":0,"explanation":"Depth approximates squared radius ratio.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz","type":"concept"},{"id":"u11-q-q14","domain":"Exoplanet evidence","prompt":"One transit event alone is:","options":["Sufficient proof in every case","Evidence requiring repeat observations and false-positive analysis","Proof of life","A direct photograph"],"answer":1,"explanation":"Repeated signals and confirmation strengthen the interpretation.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz","type":"evidence"},{"id":"u11-q-q15","domain":"Galaxy","prompt":"The Sun is located in:","options":["A globular cluster outside all galaxies","The center of the universe","The Milky Way galaxy","The Andromeda galaxy"],"answer":2,"explanation":"The Solar System is within the Milky Way.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz","type":"concept"},{"id":"u11-q-q16","domain":"Lookback time","prompt":"Observing a galaxy 10 million light-years away means seeing it approximately:","options":["10 million years in the future","With no time delay","As it is this instant","10 million years in the past"],"answer":3,"explanation":"Its light traveled for about 10 million years.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz","type":"concept"},{"id":"u11-q-q17","domain":"Redshift","prompt":"Cosmological redshift generally indicates:","options":["Increasing wavelength from large-scale recession/expansion","Chemical combustion","A star becoming visually red only","No motion or expansion"],"answer":0,"explanation":"Wavelengths are stretched in the expanding-universe context.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz","type":"concept"},{"id":"u11-q-q18","domain":"Big Bang evidence","prompt":"Which is independent evidence for a hot early universe?","options":["A solar eclipse","Cosmic microwave background","Earth’s seasons","Ocean tides"],"answer":1,"explanation":"The CMB is relic radiation from the early universe.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz","type":"evidence"},{"id":"u11-q-q19","domain":"Responsibility","prompt":"Orbital debris can:","options":["Disappear immediately","Affect only the Moon","Threaten spacecraft through high-speed collisions","Improve every orbit"],"answer":2,"explanation":"Even small debris can cause serious damage at orbital speeds.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz","type":"model"},{"id":"u11-a-a01","domain":"Earth rotation","prompt":"Earth’s west-to-east rotation makes the sky appear to move:","options":["East to west","North to south only","West to east","Without any pattern"],"answer":0,"explanation":"The apparent motion is opposite Earth’s rotation.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u11-a-a02","domain":"Seasons","prompt":"When a hemisphere tilts toward the Sun, it generally receives:","options":["Lower solar angle and shorter days","Higher solar angle and longer days","No sunlight","The same day length everywhere"],"answer":1,"explanation":"Tilt changes angle and duration.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u11-a-a03","domain":"Moon phases","prompt":"A full Moon occurs when:","options":["Earth’s shadow always covers the Moon","The Moon emits maximum light","The Moon is approximately opposite the Sun in Earth’s sky","The Moon is between Earth and the Sun"],"answer":2,"explanation":"The near side appears fully illuminated at opposition.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u11-a-a04","domain":"Light-year conversion","prompt":"Using 1 ly=9.46×10¹⁵ m, 2 ly is:","options":["9.46×10¹⁷ m","2 m","4.73×10¹⁵ m","1.892×10¹⁶ m"],"answer":3,"explanation":"2×9.46×10¹⁵=1.892×10¹⁶ m.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u11-a-a05","domain":"Light travel","prompt":"Time for light to travel 9.0×10¹⁰ m at 3.0×10⁸ m/s is:","options":["300 s","3000 s","2.7×10¹⁹ s","30 s"],"answer":0,"explanation":"t=d/c=300 s.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u11-a-a06","domain":"Orbital speed","prompt":"A circular path has r=1.0×10⁷ m and T=2.0×10⁴ s. Average speed is closest to:","options":["314 m/s","3140 m/s","31,400 m/s","6.28×10¹¹ m/s"],"answer":1,"explanation":"v=2πr/T≈3142 m/s.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"quantitative"},{"id":"u11-a-a07","domain":"Orbit direction","prompt":"For a circular orbit, velocity is approximately:","options":["Outward with no acceleration","Zero","Tangential while acceleration points inward","Inward while acceleration is tangential"],"answer":2,"explanation":"Velocity is tangent and gravity supplies inward acceleration.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"model"},{"id":"u11-a-a08","domain":"Solar-system formation","prompt":"A shared orbital plane is evidence consistent with:","options":["Independent random capture of every planet","No gravity","A stationary cloud with no angular momentum","Formation from a flattened rotating disk"],"answer":3,"explanation":"Disk formation explains common direction and plane.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"evidence"},{"id":"u11-a-a09","domain":"Planet types","prompt":"The inner planets are generally:","options":["Smaller and rocky","Larger and mostly hydrogen/helium","All dwarf planets","Made only of ice"],"answer":0,"explanation":"Mercury through Mars are terrestrial planets.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u11-a-a10","domain":"Solar fusion","prompt":"Fusion in the Sun’s core primarily converts:","options":["Light into matter only","Hydrogen into helium","Iron into hydrogen","Oxygen into carbon dioxide"],"answer":1,"explanation":"Hydrogen fusion powers the Sun.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u11-a-a11","domain":"Solar observation","prompt":"Which method is acceptable?","options":["Unfiltered camera viewfinder","Smoked glass","Certified solar filter used exactly as designed under supervision","Sunglasses with binoculars"],"answer":2,"explanation":"Only purpose-built certified protection is acceptable.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u11-a-a12","domain":"Spectrum","prompt":"An emission line occurs when:","options":["All wavelengths are absorbed equally","A planet blocks a star","A telescope loses focus","Atoms or ions emit photons at characteristic wavelengths"],"answer":3,"explanation":"Energy transitions produce characteristic photons.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u11-a-a13","domain":"Redshift calculation","prompt":"A line shifts from 600 nm to 603 nm. z is:","options":["0.005","0.05","1.005","0.0005"],"answer":0,"explanation":"z=(603−600)/600=0.005.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"quantitative"},{"id":"u11-a-a14","domain":"Velocity approximation","prompt":"For z=0.005 and c=300,000 km/s, v≈:","options":["150 km/s","1500 km/s","15,000 km/s","60,000,000 km/s"],"answer":1,"explanation":"v≈0.005×300,000=1500 km/s.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"quantitative"},{"id":"u11-a-a15","domain":"Spectral limitation","prompt":"A redshift measurement requires:","options":["No calibration","A nearby planet","A known or modeled rest wavelength for comparison","Only a color photograph"],"answer":2,"explanation":"Shift is defined relative to a rest wavelength.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u11-a-a16","domain":"Star stability","prompt":"A stable main-sequence star is in:","options":["No-gravity free expansion","Chemical equilibrium only","An orbit around every planet","Dynamic balance between gravity and pressure"],"answer":3,"explanation":"Hydrostatic balance maintains the star.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u11-a-a17","domain":"Mass and lifetime","prompt":"A high-mass star generally has:","options":["A shorter lifetime than a low-mass star","An infinite lifetime","No fusion","Lower core temperature in every case"],"answer":0,"explanation":"It consumes fuel much faster.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u11-a-a18","domain":"Supernova products","prompt":"A massive-star supernova can leave:","options":["No remnant","A neutron star or black hole","Only a rocky planet","A main-sequence Sun immediately"],"answer":1,"explanation":"Core collapse can form compact remnants.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u11-a-a19","domain":"Transit radius ratio","prompt":"A transit depth is 0.04. Rp/Rs≈:","options":["0.96","0.02","0.20","0.40"],"answer":2,"explanation":"√0.04=0.20.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"quantitative"},{"id":"u11-a-a20","domain":"Transit bias","prompt":"Which planet is easiest for a transit survey to find, all else equal?","options":["Small, long-period, face-on planet","A rogue planet with no star","A planet that never crosses the star","Large, short-period, edge-on planet"],"answer":3,"explanation":"It produces larger and more frequent transits.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u11-a-a21","domain":"Habitability claim","prompt":"Which statement is scientifically defensible?","options":["Habitable-zone position is one factor and does not prove life","Every habitable-zone planet has oceans","A transit proves biology","Atmospheres are irrelevant"],"answer":0,"explanation":"Many additional conditions and evidence are needed.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u11-a-a22","domain":"Cosmic nesting","prompt":"The Local Group is:","options":["The entire universe","A group of galaxies including the Milky Way","A group of planets around the Sun","A cluster of asteroids"],"answer":1,"explanation":"It is the Milky Way’s galactic neighborhood.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u11-a-a23","domain":"Distance evidence","prompt":"Parallax is most useful for:","options":["Measuring planet mass directly","Dating meteorites","Relatively nearby stars","The most distant galaxies only"],"answer":2,"explanation":"Parallax angles become too small at great distances.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"evidence"},{"id":"u11-a-a24","domain":"Hubble law","prompt":"At H₀=70 km/s/Mpc, d=40 Mpc gives:","options":["28,000 km/s","0.57 km/s","110 km/s","2800 km/s"],"answer":3,"explanation":"v=70×40=2800 km/s.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"quantitative"},{"id":"u11-a-a25","domain":"Hubble interpretation","prompt":"Hubble’s relation is best treated as:","options":["A large-scale empirical/model relation with scatter and calibration limits","An exact law for every nearby object","Proof Earth is central","A chemical equation"],"answer":0,"explanation":"Peculiar velocities and measurement uncertainty create scatter.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u11-a-a26","domain":"CMB evidence","prompt":"The CMB is important because it is:","options":["Proof of one specific galaxy’s age","Relic electromagnetic radiation from an early hot universe","Sunlight reflected by dust only","A local radio station"],"answer":1,"explanation":"It records conditions from the early universe.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"evidence"},{"id":"u11-a-a27","domain":"Primordial composition","prompt":"The abundance of hydrogen and helium supports:","options":["Plate tectonics","Only solar weather","Models of early-universe nucleosynthesis","Lunar-phase theory"],"answer":2,"explanation":"Predicted light-element abundances provide independent evidence.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u11-a-a28","domain":"Big Bang misconception","prompt":"Which statement is incorrect?","options":["Redshift trends support expansion","The expansion has no required ordinary spatial center","The model describes evolution from an early hot dense state","Every galaxy is moving through space away from Earth as the unique center"],"answer":3,"explanation":"Earth is not modeled as the unique expansion center.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u11-a-a29","domain":"Space responsibility","prompt":"Planetary protection aims to:","options":["Reduce harmful biological contamination between worlds","Claim ownership of planets","Increase debris","Hide all data"],"answer":0,"explanation":"It protects scientific integrity and environments.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u11-a-a30","domain":"Night observation safety","prompt":"Which plan is appropriate?","options":["Enter private land without permission","Observe with an adult from a permitted stable location away from traffic and check weather","Stand on a roof edge alone","Stop on a highway shoulder"],"answer":1,"explanation":"Safe observation requires permission, stable access, supervision, and weather awareness.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment","type":"concept"},{"id":"u12-q-q01","domain":"Problem definition","prompt":"A good need statement should:","options":["Describe users and desired improvement without assuming a solution","Exclude affected communities","Avoid measurable outcomes","Embed one required technology"],"answer":0,"explanation":"It should frame the need without premature solution lock-in.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz","type":"concept"},{"id":"u12-q-q02","domain":"Stakeholders","prompt":"A stakeholder is:","options":["Only the paying customer","Anyone affected by, using, maintaining, governing, or deciding about the system","Only the engineer","Only a regulator"],"answer":1,"explanation":"Stakeholders include many affected and responsible groups.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz","type":"concept"},{"id":"u12-q-q03","domain":"Criteria","prompt":"A criterion should be:","options":["Changed after results to favor a design","Identical to a constraint","Measurable when possible","Hidden from reviewers"],"answer":2,"explanation":"Criteria should support objective verification.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz","type":"model"},{"id":"u12-q-q04","domain":"Constraint","prompt":"A budget cap is usually:","options":["A scientific law","A test result","A feedback loop","A constraint"],"answer":3,"explanation":"It limits feasible solutions.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz","type":"model"},{"id":"u12-q-q05","domain":"Baseline","prompt":"A baseline records:","options":["Conditions before the intervention","Only the final design","A marketing claim","The preferred future without evidence"],"answer":0,"explanation":"Improvement is judged relative to current conditions.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz","type":"evidence"},{"id":"u12-q-q06","domain":"Decision matrix","prompt":"Weighted scores are most useful when:","options":["Scores are invented after selection","Weights and scoring evidence are transparent","Hard constraints are ignored","Only one concept exists"],"answer":1,"explanation":"Transparency enables review and sensitivity analysis.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz","type":"quantitative"},{"id":"u12-q-q07","domain":"Concept generation","prompt":"Why generate several concepts?","options":["To eliminate constraints","To delay all decisions forever","To reduce premature fixation and enable combination of strong features","To avoid science"],"answer":2,"explanation":"Diverse concepts increase design-space exploration.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz","type":"concept"},{"id":"u12-q-q08","domain":"Biomimicry","prompt":"A biological analogy is:","options":["A patent automatically","Always sustainable","Proof the design will work","A source of hypotheses requiring engineering tests"],"answer":3,"explanation":"Inspiration must be tested in context.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz","type":"concept"},{"id":"u12-q-q09","domain":"Prototype","prompt":"A prototype should primarily:","options":["Answer a defined design question","Look identical to the final product","Use dangerous materials","Avoid measurement"],"answer":0,"explanation":"Prototype form should match the question being tested.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz","type":"model"},{"id":"u12-q-q10","domain":"Trials","prompt":"Repeated trials help estimate:","options":["Universal optimality","Variation and repeatability","Aesthetic preference only","Legal approval"],"answer":1,"explanation":"They reveal performance spread.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz","type":"evidence"},{"id":"u12-q-q11","domain":"Uncertainty","prompt":"Measurement resolution is:","options":["A hard constraint","A stakeholder","The smallest change an instrument can meaningfully display or distinguish","The sample mean"],"answer":2,"explanation":"Resolution limits reported precision.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz","type":"evidence"},{"id":"u12-q-q12","domain":"Optimization","prompt":"Optimization means:","options":["Maximizing one criterion regardless of harm","Eliminating all tradeoffs","Ignoring failed tests","Improving performance across prioritized criteria within constraints"],"answer":3,"explanation":"Optimization is constrained and multi-criteria.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz","type":"model"},{"id":"u12-q-q13","domain":"Life cycle","prompt":"Cradle-to-grave analysis includes:","options":["Extraction through end-of-life","Use phase only","Purchase price only","Recycling only"],"answer":0,"explanation":"It considers the full life cycle.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz","type":"model"},{"id":"u12-q-q14","domain":"Functional unit","prompt":"A functional unit defines:","options":["A legal permit","The service used as the comparison basis","A company name","The criterion weight total"],"answer":1,"explanation":"It enables fair comparison of alternatives.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz","type":"concept"},{"id":"u12-q-q15","domain":"Reliability","prompt":"Reliability requires stated:","options":["Only cost","Only probability category","Function, conditions, and time","Color, logo, and owner"],"answer":2,"explanation":"Reliability is conditional on required service and context.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz","type":"evidence"},{"id":"u12-q-q16","domain":"Risk control","prompt":"Which hierarchy is strongest?","options":["Use warnings before removing the hazard","Ignore low-frequency severe hazards","Transfer all responsibility to users","Eliminate the hazard before relying only on warnings"],"answer":3,"explanation":"Elimination is generally more effective than warnings alone.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz","type":"evidence"},{"id":"u12-q-q17","domain":"Accessibility","prompt":"Universal design aims to:","options":["Increase usable access for the widest practical range of people","Design only for an average user","Remove all customization","Avoid stakeholder input"],"answer":0,"explanation":"It broadens access without unnecessary exclusion.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz","type":"concept"},{"id":"u12-q-q18","domain":"Ethics","prompt":"Informed consent is relevant when:","options":["The project is fictional","People provide personal data or participate in tests","Only machines are measured","No people are affected"],"answer":1,"explanation":"Human participation and personal data require ethical protections.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz","type":"evidence"},{"id":"u12-q-q19","domain":"Communication","prompt":"A technical claim should include:","options":["No units","No alternative explanation","Evidence, assumptions, uncertainty, and limitations","Only the strongest result"],"answer":2,"explanation":"Transparent communication supports responsible decisions.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz","type":"concept"},{"id":"u12-q-q20","domain":"Course completion","prompt":"A course completion record:","options":["Automatically grants every professional license","Eliminates future learning","Proves a design is commercially certified","Documents demonstrated coursework but does not override local credit law or policy"],"answer":3,"explanation":"Academic records do not replace jurisdictional requirements.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz","type":"concept"},{"id":"u12-a-a01","domain":"Need statement","prompt":"Which is the best need statement?","options":["Residents need safer household water treatment that is affordable, maintainable, and locally serviceable","Use ultraviolet LEDs because they are modern","Purchase the most expensive filter","Build a solar purifier immediately"],"answer":0,"explanation":"It states users and need without locking one solution.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"concept"},{"id":"u12-a-a02","domain":"Boundary","prompt":"A system boundary should identify:","options":["No exclusions","Included processes and important exchanges","Only the product color","A universal solution"],"answer":1,"explanation":"Boundaries clarify what is counted and controlled.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"model"},{"id":"u12-a-a03","domain":"Criterion","prompt":"Which is measurable?","options":["Should feel better","Must be innovative","Remove at least 95% of the specified test particles","Should be popular"],"answer":2,"explanation":"It provides a quantitative threshold and defined target.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"concept"},{"id":"u12-a-a04","domain":"Constraint","prompt":"Which is not negotiable?","options":["Highest possible score","Preferred blue color","Optional decorative feature","No exposed sharp edge during normal use"],"answer":3,"explanation":"Safety constraints are non-negotiable.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"model"},{"id":"u12-a-a05","domain":"Weights","prompt":"Weights 0.50, 0.30, and 0.20 sum to:","options":["1.00","1.20","0.50","0.80"],"answer":0,"explanation":"They sum to 1.00.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"concept"},{"id":"u12-a-a06","domain":"Weighted score","prompt":"Scores 6, 8, 9 with weights 0.5, 0.3, 0.2 give:","options":["6.6","7.2","7.8","8.4"],"answer":1,"explanation":"6×0.5+8×0.3+9×0.2=7.2.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"quantitative"},{"id":"u12-a-a07","domain":"Constraint failure","prompt":"A concept violates the maximum mass constraint. Correct action:","options":["Report it as compliant","Select it if weighted score is high","Reject or redesign it before ranking as feasible","Delete the mass constraint after testing"],"answer":2,"explanation":"Constraint failure makes it infeasible.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"model"},{"id":"u12-a-a08","domain":"Sensitivity","prompt":"A ranking that reverses under very small reasonable weight changes is:","options":["A physical law","Free of value judgments","Highly robust","Sensitive and should be reported cautiously"],"answer":3,"explanation":"Instability indicates sensitivity.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"concept"},{"id":"u12-a-a09","domain":"Mean","prompt":"Trials 12, 13, 14, 15 have mean:","options":["13.5","14","54","13"],"answer":0,"explanation":"54/4=13.5.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"quantitative"},{"id":"u12-a-a10","domain":"Range","prompt":"Trials 12, 13, 14, 15 have range:","options":["2","3","13.5","15"],"answer":1,"explanation":"15−12=3.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"quantitative"},{"id":"u12-a-a11","domain":"Percent improvement","prompt":"Baseline energy 100 kWh, redesign 70 kWh; lower is better. Improvement:","options":["70%","15%","30%","43%"],"answer":2,"explanation":"(100−70)/100=30%.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"quantitative"},{"id":"u12-a-a12","domain":"Success rate","prompt":"17 successes in 20 trials equals:","options":["117.6%","17%","20%","85%"],"answer":3,"explanation":"17/20=85%.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"quantitative"},{"id":"u12-a-a13","domain":"Systematic error","prompt":"A thermometer is consistently 1.5°C high. This is:","options":["Systematic bias","A larger sample","Reliability","Random variation"],"answer":0,"explanation":"The offset is systematic.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"evidence"},{"id":"u12-a-a14","domain":"Test validity","prompt":"Which is best?","options":["Change prototype, test load, and instrument together","Use calibrated instruments and a controlled comparison","Keep only successful trials","Round every value to a whole number"],"answer":1,"explanation":"Calibration and control support valid comparison.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"evidence"},{"id":"u12-a-a15","domain":"Material impact","prompt":"3 kg at 4 units/kg contributes:","options":["0.75 units","7 units","12 units","24 units"],"answer":2,"explanation":"3×4=12.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"concept"},{"id":"u12-a-a16","domain":"Transport impact","prompt":"Mass 2 t, distance 100 km, factor 0.05 units/(t·km) gives:","options":["100 units","1000 units","0.1 units","10 units"],"answer":3,"explanation":"2×100×0.05=10.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"concept"},{"id":"u12-a-a17","domain":"Use impact","prompt":"0.5 kWh/day for 200 days at 0.4 units/kWh gives:","options":["40 units","100 units","400 units","20 units"],"answer":0,"explanation":"0.5×200×0.4=40.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"concept"},{"id":"u12-a-a18","domain":"Annualized impact","prompt":"Total 300 units over 10 years is:","options":["3 units/year","30 units/year","290 units/year","3000 units/year"],"answer":1,"explanation":"300/10=30.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"concept"},{"id":"u12-a-a19","domain":"Recovery","prompt":"6 kg recovered from 8 kg total equals:","options":["25%","60%","75%","133%"],"answer":2,"explanation":"6/8=75%.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"quantitative"},{"id":"u12-a-a20","domain":"Life-cycle comparison","prompt":"Which is required?","options":["Same brand","Same color","Same advertising","Same functional service and compatible boundaries"],"answer":3,"explanation":"Functional equivalence and consistent boundaries enable fair comparison.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"model"},{"id":"u12-a-a21","domain":"Risk score","prompt":"Likelihood 4 × severity 5 gives:","options":["20","25","45","9"],"answer":0,"explanation":"4×5=20.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"quantitative"},{"id":"u12-a-a22","domain":"Risk reduction","prompt":"Score falls from 15 to 6. Reduction:","options":["40%","60%","90%","150%"],"answer":1,"explanation":"(15−6)/15=60%.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"quantitative"},{"id":"u12-a-a23","domain":"Series reliability","prompt":"Independent reliabilities 0.95 and 0.80 give:","options":["0.95","1.75","0.76","0.875"],"answer":2,"explanation":"0.95×0.80=0.76.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"quantitative"},{"id":"u12-a-a24","domain":"Redundancy","prompt":"A backup pump primarily improves:","options":["Material toxicity","Criterion ambiguity","Stakeholder exclusion","Functional resilience if the primary fails"],"answer":3,"explanation":"A backup can preserve required service.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"concept"},{"id":"u12-a-a25","domain":"Residual risk","prompt":"After controls, remaining risk should be:","options":["Documented, reviewed, and accepted or further reduced","Assumed zero","Converted into a preference","Hidden"],"answer":0,"explanation":"Residual risk needs accountable treatment.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"evidence"},{"id":"u12-a-a26","domain":"Accessibility","prompt":"Which is most inclusive?","options":["Single tiny text-only control","Multiple perceivable control methods with clear labels","Color-only warnings","Steps requiring perfect grip strength"],"answer":1,"explanation":"Multiple accessible modes reduce exclusion.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"concept"},{"id":"u12-a-a27","domain":"Privacy","prompt":"A prototype app collects location data. Best practice:","options":["Use hidden tracking","Collect everything indefinitely","Minimize collection, obtain consent, secure data, and define deletion","Publish raw records"],"answer":2,"explanation":"Privacy-by-design reduces risk.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"evidence"},{"id":"u12-a-a28","domain":"Optimization","prompt":"A redesign improves efficiency but doubles injury risk. It is:","options":["Proven sustainable","Ready for release","Automatically optimal","Not acceptable without addressing safety constraint and tradeoff"],"answer":3,"explanation":"Optimization cannot ignore safety.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"evidence"},{"id":"u12-a-a29","domain":"Communication","prompt":"Which statement is strongest?","options":["Under the stated tests, mean performance improved 18%, with a 4% range and two untested conditions","Everyone will benefit","No uncertainty exists","The design is perfect"],"answer":0,"explanation":"It reports evidence, variability, and limits.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"concept"},{"id":"u12-a-a30","domain":"Capstone","prompt":"A defensible engineering conclusion should connect:","options":["Only the first prototype","Need, science, criteria, test data, life cycle, risk, revision, and stakeholder impacts","Only appearance","Only lowest cost"],"answer":1,"explanation":"A capstone integrates the full evidence chain.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment","type":"concept"}];
